set-query-parameter.value:
@{
                        var combinedGroups = "";

                        var roles = ((Jwt)context.Variables["jwt"]).Claims["roles"];
                        foreach (var role in roles)
                        {
                            if (role.EndsWith(".Read"))
                            {
                                var roleName = role.Substring(0, role.IndexOf(".Read"));

                                if(!string.IsNullOrEmpty(combinedGroups)) {
                                    combinedGroups += "&security_groups=";
                                }

                                combinedGroups += roleName;
                            }
                        }

                        return combinedGroups;    
                    }
